import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int groups
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_len_idx = blockIdx.z * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || out_len_idx >= output_length) {
        return;
    }

    int group_size = in_channels / groups;
    int weight_offset = out_ch_idx * group_size * kernel_size;
    int input_offset = batch_idx * in_channels * input_length + out_ch_idx * group_size * input_length;

    half sum = __float2half(0.0f);

    for (int k = 0; k < kernel_size; k++) {
        int input_pos = out_len_idx * stride - padding + k * dilation;
        if (input_pos >= 0 && input_pos < input_length) {
            int weight_idx = weight_offset + k;
            int input_idx = input_offset + input_pos;
            sum = __hadd(sum, __hmul(weight[weight_idx], input[input_idx]));
        }
    }

    int output_idx = batch_idx * out_channels * output_length + out_ch_idx * output_length + out_len_idx;
    output[output_idx] = sum;
}

// Wrapper function for easier calling
extern "C" void launch_conv1d(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int groups
) {
    dim3 block_size(256);
    dim3 grid_size(batch_size, out_channels, (output_length + 255) / 256);
    conv1d_kernel<<<grid_size, block_size>>>(
        input, weight, output,
        batch_size, in_channels, out_channels,
        input_length, output_length,
        kernel_size, stride, padding, dilation, groups
    );
    cudaDeviceSynchronize();
}
"""

# Python wrapper class
class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias

        # Initialize weights
        self.weight = torch.nn.Parameter(torch.randn(out_channels, in_channels // groups, kernel_size).half())
        if bias:
            self.bias = torch.nn.Parameter(torch.randn(out_channels).half())
        else:
            self.register_parameter('bias', None)

        # Compile CUDA kernel
        self.conv_module = load_inline(
            name="conv1d_kernel",
            cpp_sources=cuda_source,
            cuda_sources=cuda_source,
            functions=["launch_conv1d"],
            verbose=False
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, _, input_length = x.shape

        # Calculate output length
        output_length = (input_length + 2 * self.padding - (self.dilation * (self.kernel_size - 1) + 1)) // self.stride + 1

        # Prepare output tensor
        output = torch.empty(batch_size, self.out_channels, output_length, dtype=torch.float16, device=x.device)

        # Launch CUDA kernel
        self.conv_module.launch_conv1d(
            x.contiguous().data_ptr(),
            self.weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            self.out_channels,
            input_length,
            output_length,
            self.kernel_size,
            self.stride,
            self.padding,
            self.dilation,
            self.groups
        )

        # Add bias if present
        if self.bias is not None:
            output += self.bias.view(1, -1, 1)

        return output

